#include <iostream>
#include <map>
#include <stack>
#include <string>

bool isBalanced(const std::string& text) {
    const std::map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    std::stack<char> stack;
    for (char ch : text) {
        auto match = pairs.find(ch);
        if (match == pairs.end()) {
            stack.push(ch);
        } else {
            if (stack.empty() || stack.top() != match->second) {
                return false;
            }
            stack.pop();
        }
    }
    return stack.empty();
}

int main() {
    std::string text;
    std::getline(std::cin, text);
    std::cout << (isBalanced(text) ? "true" : "false") << "\n";
    return 0;
}

