package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func isBalanced(text string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}
	for _, ch := range text {
		if open, isClose := pairs[ch]; isClose {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	text := strings.TrimSpace(scanner.Text())
	if isBalanced(text) {
		fmt.Println("true")
	} else {
		fmt.Println("false")
	}
}
